    choose: [['It could (be / being) a good opportunity.', 'be'], ['I might (stay / stayed) in Kyoto.', 'stay'], ['One advantage (is / are) being near my family.', 'is'], ['I would miss (my friends / to my friends).', 'my friends'], ['I have not decided (yet / already).', 'yet'], ['I need to ask (about / of) the role.', 'about']],
