export const newPathsId = (number: StoryLessonNumber) => `conversational-skills-L4-C2-${number}-${newPathsEpisodes[number].skill}-ja-v1`;
export function buildNewPathsLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: newPathsEpisodes[number], id: newPathsId(number), chapterName: 'New Paths, Unexpected Feelings',
    setting: 'Kamo House cafe, its kitchen and the Kamo River in Kyoto; a fictional Osaka design agency. Leo receives work messages from his former manager in Bristol.',
    previousSummary: index === 0 ? 'After the hidden dinner and false work message, Leo ended his relationship with Emma. Only afterward, his former Bristol manager contacted him about a new bakery. Leo had not accepted or decided to move. A few weeks have passed.' : newPathsEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: 'Adapted from the supplied New Paths, Unexpected Feelings outline (Level 4 Chapter 2): Bristol offer, photo walk, Emma career achievement, market proposal, pastry mistake, appreciation/coffee, Bristol decline, successful market/date invitation. Story slots1-4/6-9,5/10 dynamic checkpoints. Speaking/listening/reading/speaking then speaking/speaking/reading/speaking. A few weeks after the Level 4 Chapter 1 breakup; do not undo it, repeat the removed physical incident, or portray Nao as romantic before this chapter. Leo decides to stay for skills/community and future ambition, not solely for Nao. His own bakery is an unplanned future hope. Market nextSaturday10-1; recipe test before market; Tuesday coffee accepted; Bristol Friday reply deadline, Fridayafter5 tray pickup, Mondaybeforenoon tray return, nextWednesday3 seasonal recipe discussion. Keep different Friday actions distinct. Emma stays professionally connected to Ren, leads Osaka exhibition project, contributes congratulations remotely, and is not forced into a meeting with Leo. Nao/Leo friendship grows into clear date invitations; no physical intimacy. The story continues in Level 4 Chapter 3; Chapters 4-5 await user outlines. Short supported B1-B2 language, direct roles, no personal disclaimers or compulsory monologues, standard tutor guides/rubric and actual-error tracking, Japanese support. No new images.',
  });
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Kyoto-based designer in a hybrid Osaka role. Rebuilds professional confidence, leads an exhibition design project and keeps contact with Ren professional.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Baker weighing Bristol against Kyoto. Chooses Kyoto for skills, community and a future bakery ambition; develops feelings for Nao.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist and photographer. Helps with recipe testing, sells cups at the market and accepts clear invitations from Leo.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Kamo House cafe organiser. Shares market jobs and invites Emma separately without assuming availability or forcing a reunion.' },
    { id: 'ren', name: 'Ren', role: 'supporting', description: 'Osaka design coworker. Provides professional feedback and image checks within the team, not renewed personal pressure.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 4, chapter: 2, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 2: New Paths, Unexpected Feelings', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja' };
}
export function buildNewPathsChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildNewPathsLesson(number, {}, reference));
}
